{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss encourages the model to favor pairs where the advantage difference aligns with the cost gap, promoting preferred outcomes by weighting pairs based on advantage and cost difference, thus directly optimizing for lower costs when advantages suggest better quality.",
  "pseudocode": "loss = -logsigmoid( advantage_w - advantage_l + alpha * (cost_gap) ) * (weight) + epsilon",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "advantage_based",
    "link_family": "sigmoid",
    "agg_family": "pairwise",
    "constraint_family": "cost_advantage_alignment",
    "other_hparams": "alpha=1.0"
  },
  "operators_used": ["logsigmoid", "mul", "add"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    advantage_w = batch[\"advantage_w\"]\n    advantage_l = batch[\"advantage_l\"]\n    cost_gap = batch[\"cost_gap\"]\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    weight = batch[\"weight\"]\n    signal = ops.sub(advantage_w, advantage_l)\n    cost_signal = ops.mul(alpha, cost_gap)\n    combined_signal = ops.add(signal, cost_signal)\n    loss = ops.neg(ops.logsigmoid(combined_signal))\n    weighted_loss = ops.mul(loss, weight)\n    final_loss = ops.mean(weighted_loss)\n    return final_loss"
}

{
  "name": "loss_pairwise_ranking_margin_exp_advantage",
  "intuition": "Use an exponential margin ranking loss weighted by advantage gap to emphasize larger preference margins and advantage signals, combining a softplus link with weighted pairwise ranking aggregation.",
  "pseudocode": "margin = advantage_w - advantage_l\nscore_diff = log_prob_w - log_prob_l\nloss_per_pair = softplus(-score_diff * margin)\nweighted_loss = loss_per_pair * weight\nloss = mean(weighted_loss)",
