  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    margin = ops.sub(adv_w, adv_l)\n    score_diff = ops.sub(lpw, lpl)\n    loss_per_pair = ops.softplus(ops.neg(ops.mul(score_diff, margin)))\n    if weight is not None:\n        loss_per_pair = ops.mul(loss_per_pair, weight)\n    return ops.mean(loss_per_pair)"
}

