{
  "name": "stabilized_cost_logprob_hybrid_loss",
  "intuition": "Simplified and stabilized the hybrid loss by combining a cost gap term and a scaled log probability difference term inside a single logsigmoid for numerical stability. Removed redundant second logsigmoid to reduce complexity and potential instability. Applied clamping on combined logits to [-20,20] to avoid extreme values causing overflow. This retains semantic meaning and stabilizes training while simplifying the expression.",
  "pseudocode": "1. Compute cost gap: gap = cost_b - cost_a (detached)\n2. Compute combined score: x = alpha * scale * (log_prob_w - log_prob_l) - slope * gap\n3. Clamp x between -20 and 20 to stabilize\n4. Apply negative logsigmoid on x\n5. Multiply by optional sample-wise weight\n6. Average over batch",
  "hyperparams": {
    "alpha": 1.0,
    "scale": 1.5,
    "slope": 0.1
  },
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "cost_a",
      "cost_b"
    ]
  },
  "generated_loss": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('scale', extra.get('hyperparams', {}).get('scale', 1.5)))\n    slope = float(extra.get('slope', extra.get('hyperparams', {}).get('slope', 0.1)))\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    gap = (cost_b - cost_a).detach()\n    x = alpha * scale * (lpw - lpl) - slope * gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    weight = batch.get('weight', None)\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()"
}

{
  "name": "pairwise_advantage_gap_loss",
  "intuition": "This loss leverages the advantage gap to promote better ranking by encouraging pairs where the advantage difference is positive, with a focus on stable, cost-aware preference signals. The advantage gap provides a direct measure of how much better one option is over another, encouraging the model to favor more advantageous choices while penalizing less favorable pairs.",
  "pseudocode": "scalar = mean( logsigmoid( log_prob_w - log_prob_l + advantage_gap ) )",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "advantage",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "cost_aware",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "mean", "sub"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    advantage_gap = batch.get('advantage_gap', ops.zeros_like(log_prob_w))\n    weight = batch['weight']\n    preference_score = ops.logsigmoid( ops.sub(ops.sub(log_prob_w, log_prob_l), advantage_gap) )\n    weighted_score = ops.mul(preference_score, weight)\n    return ops.mean(weighted_score)"
}

{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss encourages selecting pairs with higher advantage (benefit) while penalizing cost gaps, aligning the model to prefer better performing options. Using advantage and cost gap ensures the model focuses on comparative benefits, promoting preference correctness.",
  "pseudocode": "loss = -mean(logsigmoid advantage_w - logsigmoid advantage_l + lambda * cost_gap)",
  "hyperparams": {
    "paradigm_family": "pairwise_comparison",
    "signal_family": "advantage_and_cost",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "pairwise"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    cost_gap = batch.get('cost_gap', ops.zeros_like(advantage_w))\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    # Hyperparameter lambda for cost gap influence\n    lambda_coeff = float(extra.get('lambda', 1.0))\n    # Compute pairwise sigmoid advantage signals\n    adv_w = ops.logsigmoid(advantage_w)\n    adv_l = ops.logsigmoid(advantage_l)\n    # Compute loss as negative mean of advantage differences plus penalization for cost gap\n    loss = -ops.mean(ops.add(adv_w, ops.neg(adv_l)))\n    loss = ops.add(loss, lambda_coeff * ops.mean(cost_gap))\n    return loss"
}
